public protocol EngineViewProtocol: AnyObject, Sendable {
    
    func backend()  -> String
    
    func cameraJson()  -> String
    
    func frameAll() 
    
    /**
     * The object and world point under a screen point (pixels).
     */
    func hit(x: Float, y: Float)  -> Hit?
    
    func openProject(bytes: Data) throws 
    
    func orbit(dx: Float, dy: Float) 
    
    func pan(dx: Float, dy: Float) 
    
    /**
     * Screen points are in the layer's pixels (points times scale), top left origin.
     */
    func pick(x: Float, y: Float)  -> String?
    
    /**
     * Screen x, y (pixels) and clip depth of a world point; empty when behind the camera.
     */
    func project(x: Float, y: Float, z: Float)  -> [Float]
    
    func projectJson()  -> String?
    
    func redo()  -> Bool
    
    func removeObject(id: String) 
    
    /**
     * Draws one frame into the layer or window. Call from the host's display link.
     */
    func render() 
    
    func resize(width: UInt32, height: UInt32) 
    
    func sculptBegin(x: Float, y: Float, pressure: Float)  -> Bool
    
    func sculptCancel() 
    
    /**
     * The `SceneCommand.setMesh` JSON to pass to the Swift core's `perform` / `apply` ("Sculpt").
     */
    func sculptEnd()  -> String?
    
    func sculptMove(x: Float, y: Float, pressure: Float) 
    
    /**
     * kind: "draw", "inflate", "smooth", "flatten"; radius in world mm; strength -1 to 1.
     */
    func setBrush(kind: String, radius: Float, strength: Float, symmetryX: Bool) 
    
    func setCameraJson(json: String) throws 
    
    func setHighlight(id: String, on: Bool) 
    
    /**
     * "agx", "aces" or "linear".
     */
    func setLook(tonemap: String, ssao: Bool, shadows: Bool) 
    
    func setMaterial(id: String, color: [Float], metallic: Float, roughness: Float) throws 
    
    func setTransform(id: String, world: [Float]) throws 
    
    func setVisible(id: String, visible: Bool) 
    
    /**
     * Renders the current scene offscreen to PNG bytes (any view, surface or not).
     */
    func snapshotPng(width: UInt32, height: UInt32)  -> Data
    
    func undo()  -> Bool
    
    /**
     * Adds or replaces an object from the host's scene: base mesh JSON (Sculptor's Mesh shape), column
     * major world matrix (16 floats, millimetres, Z up), sRGB colour (4 floats), metallic, roughness.
     */
    func upsertObject(id: String, meshJson: String, world: [Float], color: [Float], metallic: Float, roughness: Float) throws 
    
    func zoom(factor: Float) 
    
}
